package main

import (
	"errors"
	"fmt"
)

type Server struct {
	Host    string
	Port    int
	MaxConn int
}

type Option func(*Server) error

func WithHost(h string) Option {
	return func(s *Server) error {
		if h == "" { return errors.New("host не может быть пустым") }
		s.Host = h
		return nil
	}
}

func WithPort(p int) Option {
	return func(s *Server) error {
		if p < 1 || p > 65535 { return fmt.Errorf("неверный порт: %d", p) }
		s.Port = p
		return nil
	}
}

func NewServer(opts ...Option) (*Server, error) {
	srv := &Server{Host: "127.0.0.1", Port: 8080, MaxConn: 100}
	for _, opt := range opts {
		if err := opt(srv); err != nil {
			return nil, err
		}
	}
	return srv, nil
}

func main() {
	s, err := NewServer(WithHost("0.0.0.0"), WithPort(9000))
	if err != nil { panic(err) }
	fmt.Printf("Сервер успешно сконфигурирован: %s:%d\n", s.Host, s.Port)
}

package main

import (
	"fmt"
	"reflect"
)

type Device struct {
	Model string
	Price float64
}

func (d Device) Info() string { return d.Model }
func (d Device) Discount()    {}

func StructInfo(v any) {
	t := reflect.TypeOf(v)
	fmt.Println("=== Тип:", t.Name(), "===")
	fmt.Println("Поля:")
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		fmt.Printf("  - %-8s : %s\n", f.Name, f.Type)
	}
	fmt.Println("Методы:")
	for i := 0; i < t.NumMethod(); i++ {
		m := t.Method(i)
		fmt.Printf("  - %s()\n", m.Name)
	}
}

func main() {
	StructInfo(Device{Model: "MacBook M3", Price: 200000})
}

