import "fmt"

type Observer interface {
	Update(event string)
}

type Subject struct {
	observers []Observer
}

func (s *Subject) Subscribe(o Observer)   { s.observers = append(s.observers, o) }
func (s *Subject) Notify(event string) {
	for _, o := range s.observers {
		o.Update(event)
	}
}

type EmailAlert struct{ Email string }
func (e EmailAlert) Update(ev string) { fmt.Printf("📧 Отправка письма на %s: %s\n", e.Email, ev) }

type LogAlert struct{}
func (LogAlert) Update(ev string) { fmt.Printf("📝 Запись в журнал: %s\n", ev) }

func main() {
	s := &Subject{}
	s.Subscribe(EmailAlert{"admin@company.ru"})
	s.Subscribe(LogAlert{})
	s.Notify("Сбой в кластере Kafka!")
}

package main

import (
	"errors"
	"fmt"
	"sync"
)

type User struct {
	ID   int
	Name string
}

type UserRepository interface {
	Create(u *User) error
	FindByID(id int) (*User, error)
}

type InMemoryUserRepository struct {
	mu    sync.RWMutex
	users map[int]*User
}

func NewInMemoryUserRepository() *InMemoryUserRepository {
	return &InMemoryUserRepository{users: make(map[int]*User)}
}

func (r *InMemoryUserRepository) Create(u *User) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	r.users[u.ID] = u
	return nil
}

func (r *InMemoryUserRepository) FindByID(id int) (*User, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	u, ok := r.users[id]
	if !ok { return nil, errors.New("пользователь не найден") }
	return u, nil
}

func main() {
	var repo UserRepository = NewInMemoryUserRepository()
	_ = repo.Create(&User{ID: 1, Name: "Артем"})
	u, _ := repo.FindByID(1)
	fmt.Println("Найден пользователь:", u.Name)
}

package main

import (
	"fmt"
	"strings"
)

type Processor interface {
	Process(string) string
}

type StringProcessor func(string) string

func (f StringProcessor) Process(s string) string {
	return f(s)
}

func ProcessAll(p Processor, items []string) []string {
	var res []string
	for _, item := range items {
		res = append(res, p.Process(item))
	}
	return res
}

func main() {
	// Обычная функция:
	toUpper := func(s string) string { return strings.ToUpper(s) }

	// Адаптируем к интерфейсу Processor:
	results := ProcessAll(StringProcessor(toUpper), []string{"golang", "patterns"})
	fmt.Println(results)
}

