import (
	"fmt"
	"sync"
)

type SafeCounter struct {
	mu  sync.Mutex
	val int
}

// ✅ ИСПРАВЛЕНИЕ: Pointer Receiver (*SafeCounter)
func (c *SafeCounter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.val++
}

func (c *SafeCounter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.val
}

func main() {
	c := &SafeCounter{}
	c.Inc()
	c.Inc()
	fmt.Println("Итоговый счетчик:", c.Value())
}

package main

import (
	"fmt"
	"sync"
)

type AtomicCounter struct {
	mu  sync.Mutex
	val int
}

func (c *AtomicCounter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.val++
}

func main() {
	c := &AtomicCounter{}
	var wg sync.WaitGroup

	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Inc()
		}()
	}

	wg.Wait()
	fmt.Println("Счетчик после 100 горутин:", c.val)
}

